<script setup lang="ts">
import{ref,computed}from'vue';import{Search,ChevronDown,ChevronRight,UserRound}from'lucide-vue-next';import type{Candidate}from'../../types/election';import{percent,number,normalize,palette}from'../../utils/format';const props=defineProps<{candidates:Candidate[];loading:boolean;office:string}>();const expanded=ref(false),query=ref(''),broken=ref<Record<string,boolean>>({});const filtered=computed(()=>props.candidates.filter(c=>normalize(c.name).includes(normalize(query.value))||c.number.includes(query.value)));const visible=computed(()=>expanded.value||query.value?filtered.value:filtered.value.slice(0,5));
</script>
<template><section class="panel candidate-panel"><div class="panel-heading"><div><h2>Candidatos</h2><p>Votos recebidos nesta localização</p></div><span class="muted small">{{candidates.length||'—'}} candidatos</span></div><label v-if="['6','7','8'].includes(office)" class="input-search candidate-search"><Search :size="17"/><input v-model="query" placeholder="Buscar por nome ou número" aria-label="Buscar candidato"></label><div class="candidate-column-label"><span>CANDIDATO</span><span>VOTOS / %</span></div><div v-if="loading" class="candidate-skeleton" aria-label="Carregando candidatos"><div v-for="i in 5" :key="i" class="skeleton-row"><span class="skeleton circle"></span><span class="skeleton"></span><span class="skeleton"></span></div></div><div v-else-if="!candidates.length" class="empty-state"><UserRound :size="30"/><h3>Aguardando candidatos</h3><p>Os dados serão exibidos assim que a consulta ao TSE estiver disponível.</p></div><RouterLink v-for="(c,i) in visible" :key="c.id" :to="`/candidato/${c.id}?uf=${c.uf}&cargo=${c.office}`" class="candidate-row"><span class="candidate-avatar" :style="{'--candidate-color':palette[i%palette.length]}"><img v-if="!broken[c.id]" :src="c.photo" :alt="c.name" loading="lazy" @error="broken[c.id]=true"><UserRound v-else :size="25"/></span><div class="candidate-info"><div class="candidate-name">{{c.name}} <ChevronRight :size="14"/></div><div class="candidate-meta"><span>{{c.party}}</span><span class="candidate-number">{{c.number}}</span><span class="candidate-situation" :class="{elected:c.status.toLowerCase().includes('eleito')&&!c.status.toLowerCase().includes('não')}">{{c.status}}</span></div><div class="candidate-bar"><span :style="{width:(c.percent??0)+'%',background:palette[i%palette.length]}"></span></div></div><div class="candidate-votes"><strong>{{percent(c.percent)}}</strong><span>{{number(c.votes)}} votos</span></div></RouterLink><p v-if="query&&!filtered.length" class="empty-state">Nenhum candidato encontrado.</p><button v-if="candidates.length>5&&!query" class="all-candidates" @click="expanded=!expanded">{{expanded?'Mostrar principais candidatos':`Ver todos os ${candidates.length} candidatos`}}<ChevronDown :size="16" :style="{transform:expanded?'rotate(180deg)':''}"/></button><div class="panel-footnote">Percentuais e situação conforme informados pelo TSE.</div></section></template>
